import React, { useEffect, useState } from 'react';
import api from './api.ts';
import { userInfo } from 'os';
import logoclara from './img/logo-clara.png';
import logoescura from './img/logo-escura.png';
import logobranca from './img/logo-branca.png';

interface User {
  email: string;
  nome: string;
  role: 'admin' | 'licenciado';
}

interface Notice {
  id: number;
  message: string;
  created_at: string;
}

interface FileData {
  id: number;
  filename: string;
  originalname: string;
  uploaded_at: string;
}

const App: React.FC = () => {
  const [email, setEmail] = useState('');
  const [nome, setNome] = useState('');
  const [password, setPassword] = useState('');
  const [user, setUser] = useState<User | null>(null);
  const [notices, setNotices] = useState<Notice[]>([]);
  const [files, setFiles] = useState<FileData[]>([]);
  const [message, setMessage] = useState('');
  const [file, setFile] = useState<File | null>(null);

  const handleLogin = async () => {
    try {
      const res = await api.post('/api/login', { email, password });
      setUser(res.data);
    } catch (err) {
      alert('Revise os dados de login e tente novamente');
    }
  };

  const fetchData = async () => {
    const [nRes, fRes] = await Promise.all([
      api.get('/api/notices'),
      api.get('/api/files')
    ]);
    setNotices(nRes.data);
    setFiles(fRes.data);
  };

  const handlePostNotice = async () => {
    await api.post('/api/admin/notice', { message });
    setMessage('');
    fetchData();
  };

  const handleUpload = async () => {
    if (!file) return;
    const formData = new FormData();
    formData.append('file', file);
    await api.post('/api/admin/upload', formData, {
      headers: { 'Content-Type': 'multipart/form-data' },
    });
    setFile(null);
    fetchData();
  };

  const [mostrarRecuperacao, setMostrarRecuperacao] = useState(false);

  const [emailRecuperacao, setEmailRecuperacao] = useState('');

  const handleRecuperarSenha = async () => {
  try {
    const response = await fetch('http://localhost:3001/redefinir-senha', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: emailRecuperacao }),
    });

    const result = await response.json();
    if (response.ok) {
      alert('Email de recuperação enviado com sucesso!');
    } else {
      alert(result.message || 'Erro ao enviar recuperação.');
    }
    } catch (error) {
      alert('Erro na requisição.');
      console.error(error);
    }
  };

  useEffect(() => {
    if (user) fetchData();
  }, [user]);

  if (!user) {
  return (
    <div>
      <div className="p-img">
        <img alt="Logo da Valor Fiscal" src={logoclara} />
      </div>
      <div className="p-1">
        <h2 className="titulo-login">
          Painel do Licenciado
        </h2>

        {!mostrarRecuperacao ? (
          <>
            <input
              type="email"
              placeholder="Email"
              className="input-login"
              onChange={e => setEmail(e.target.value)}
            />
            <input
              type="password"
              placeholder="Senha"
              className="input-login"
              onChange={e => setPassword(e.target.value)}
            />
            <button className="botao-login" onClick={handleLogin}>Login</button>
            <p>
              <a href="#" onClick={() => setMostrarRecuperacao(true)}>
                Esqueceu sua senha?
              </a>
            </p>
          </>
        ) : (
          <>
            <input
              type="email"
              placeholder="Digite seu email para recuperação"
              className="input-login"
              onChange={e => setEmailRecuperacao(e.target.value)}
            />
            <button className="botao-login" onClick={handleRecuperarSenha}>
              Enviar recuperação
            </button>
            <p>
              <a href="#" onClick={() => setMostrarRecuperacao(false)}>
                Voltar para login
              </a>
            </p>
          </>
        )}
      </div>
    </div>
  );
  }


  return (
    <div className="p-2">
      <h2 className="subtitulo">
        Bem vindo ao novo
      </h2>
      <h2 className="titulo">
        Painel do Licenciado!
      </h2>



    </div>
  );
};

export default App;
